import {graphViewports} from './graph-viewport.mjs';
import {cycleAnalysis,cycleCandidates,cycleGraphData} from './cycle-model.mjs';
import {deploymentVisual} from './view-model.mjs';
const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class CycleWorkbench{
 constructor(options){this.o=options;this.scope='active';this.overrides=new Map();this.selected=null;this.edge=null;this.product=null;this.downstream=false;this.scopeKey=null;this.currentCy=null;document.addEventListener('click',e=>this.click(e));document.addEventListener('change',e=>this.change(e));}
 ensure(){const scope=this.o.scope();if(scope!==this.scopeKey){this.scopeKey=scope;this.overrides.clear();this.selected=null;this.edge=null;this.product=null;this.downstream=false;this.scope='active'}this.analysis=cycleAnalysis(this.o.model(),this.overrides,this.o.productTrials?.()||new Set());return this.analysis;}
 name(id){return this.analysis.before.by.get(id)?.product_name||id}
 panelHTML(){const a=this.ensure(),g=a.groups.find(g=>g.key===this.selected),shown=a.groups.filter(g=>this.scope==='all'||(this.scope==='active'?g.active:!g.active)).sort((x,y)=>Number(y.active)-Number(x.active)||y.affected.length-x.affected.length);return `<section id="cycleWorkbench" class="cycle-workbench"><div class="cycle-title"><div><b>循環決策工作區</b><p>目前阻擋 ${a.activeGroups} 組 · 結構循環 ${a.structuralGroups} 組；群組數不等於單一迴圈數。</p></div><select id="cycleScope" aria-label="循環範圍"><option value="active" ${this.scope==='active'?'selected':''}>目前阻擋中</option><option value="all" ${this.scope==='all'?'selected':''}>全部結構循環</option><option value="resolved" ${this.scope==='resolved'?'selected':''}>目前無阻擋循環</option></select></div>${g?`<div class="cycle-selected"><div><b>${g.code} · ${g.members.length} 項產品 · ${g.departments.size} 個部門</b><span class="cycle-status ${g.active?'blocking':'resolved'}">${g.active?'循環阻擋中':g.baselineCycles.length?'試算已解除':'目前無等待循環'}</span><p>${escape(g.members.map(id=>this.name(id)).join('、'))}</p><small>受影響下游 ${g.downstream.size} 項（其中 ${g.affected.length} 項待部署） · 單擊產品僅聚焦，不切換上游視角。</small></div><div class="tools"><button data-cycle-back>返回循環總覽</button><button data-cycle-downstream>${this.downstream?'收合下游':'查看受影響下游'}</button>${this.product?`<button data-cycle-product-evidence="${escape(this.product)}">產品正式證據</button>`:''}</div></div><details class="cycle-gates"><summary>檢討環內依賴（${g.internal.length} 條）</summary><p>暗紅實線＝未滿足；灰色虛線＝已滿足或試算調整。點擊依賴查看證據並建立方案。</p>${this.gateList(g)}</details>`:`<p class="cycle-hint">選擇一組循環，查看完整環內產品與依賴；下游預設收合。</p><div class="cycle-list">${shown.map(g=>`<button class="cycle-row" data-cycle-select="${escape(g.key)}" aria-label="檢視循環群組 ${g.code}"><b>${g.code} · ${g.members.length} 項產品</b><span>${g.departments.size} 部門 · 待部署下游 ${g.affected.length} 項</span><small>${escape(g.members.map(id=>this.name(id)).join('、'))}</small><em>${g.active?'目前阻擋':g.baselineCycles.length?'試算已解除':'目前無等待循環'} ↗</em></button>`).join('')||'<p class="empty">此範圍沒有循環群組；可切換「全部結構循環」查看。</p>'}</div>`}${this.overrides.size?this.trialSummary():''}<div id="cycleDownstreamList"></div></section>`;}
 gateList(g){const candidates=new Set(cycleCandidates(this.analysis.after,g));return g.internal.map(e=>{const plan=this.overrides.get(e.edge_id),met=this.analysis.after.met(e);return `<button class="cycle-gate-row" data-cycle-edge="${escape(e.edge_id)}"><span>${escape(this.name(e.source))} → ${escape(this.name(e.target))}</span><small>${plan?'已套用試算':met?'條件已滿足':'等待 '+escape(e.temporal_constraint.predecessor_state||'Ready')}${candidates.has(e.edge_id)?' · 結構檢討候選':''}</small></button>`}).join('');}
 trialSummary(){const a=this.analysis,departments=new Set(a.newlyReady.map(r=>r.node.department_id));return `<div class="cycle-trial-summary"><b>依賴調整試算 · 正式資料未修改</b><div class="cycle-metrics"><span>阻擋循環組<strong>${a.groups.filter(g=>g.baselineCycles.length).length} → ${a.activeGroups}</strong></span><span>新增前置就緒<strong>+${a.newlyReady.length}</strong></span><span>新增就緒部門<strong>${departments.size}</strong></span><span>未滿足條件<strong>${a.before.gates.filter(e=>!a.before.met(e)).length} → ${a.after.gates.filter(e=>!a.after.met(e)).length}</strong></span></div><details><summary>調整項目（${this.overrides.size}）及新增就緒產品</summary>${[...this.overrides].map(([id,p])=>`<div class="cycle-plan-row"><span>${escape(p.sourceName)} → ${escape(p.targetName)}<small>${escape(p.kindLabel)} · ${escape(p.owner)} · ${escape(p.reason)}${p.condition?' · '+escape(p.condition):''}</small></span><button data-cycle-remove="${escape(id)}">取消此調整</button></div>`).join('')}<p>${a.newlyReady.map(r=>escape(r.node.product_name)+'（'+escape(r.node.department_name)+'）').join('、')||'尚無新增前置就緒產品；仍有其他必要條件未滿足。'}</p></details><div class="tools"><button data-cycle-reset>清除依賴調整試算</button><button data-cycle-export>匯出決策草案</button></div><small>解除循環不等於可以開工；就緒仍依全部必要條件判定。此處不推估缺乏資料的工期與資源。</small></div>`;}
 refresh(){if(this.o.activeDecision?.()){this.ensure();this.o.updated();return}if(!$('#cycleWorkbench'))return;$('#cycleWorkbench').outerHTML=this.panelHTML();this.draw();if(this.edge&&$('#sideDrawer')?.open&&document.querySelector('[data-drawer-pane="cycle"]:not([hidden])'))this.o.openEdge();}
 select(key){if(this.o.openDecision){this.ensure();this.selected=key;this.edge=null;this.product=null;this.downstream=false;const group=this.analysis.groups.find(g=>g.key===key);if(group)this.o.openDecision(group);return}this.selected=key;this.edge=null;this.product=null;this.downstream=false;this.refresh()}
 selectProduct(id){this.ensure();const g=this.analysis.groups.find(g=>g.members.includes(id));if(!g){this.o.toast('此產品不屬於循環群組；請切換其他 Graph 視角查看');return}this.selected=g.key;this.product=id;this.refresh();this.focusProduct(id);}
 focusProduct(id){this.product=id;const cy=this.currentCy;cy.nodes().removeClass('cycle-focus');cy.getElementById('product:'+id).addClass('cycle-focus');const input=$('#graphProductSearch');if(input)input.value=this.name(id);}
 readable(){const cy=this.currentCy;if(!cy||cy.destroyed()||!cy.nodes().length)return;cy.zoom(.75);if(this.selected){const target=cy.getElementById('product:'+this.product);if(target.length)cy.center(target);else cy.center(cy.nodes().filter(n=>n.data('kind')==='product'))}else{const node=cy.nodes().first();cy.center(node)}this.o.zoomUI();}
 draw(){const host=$('#graph');if(!host||!host.getClientRects().length)return;this.ensure();graphViewports.remember();if(this.currentCy&&!this.currentCy.destroyed())this.currentCy.destroy();host.replaceChildren();const data=cycleGraphData(this.analysis,this.selected,this.downstream,this.scope),elements=[];for(const n of data.nodes){let svg,label='';if(n.kind==='product'){const r=this.analysis.after.results.get(n.members[0]);svg=this.o.nodeSVG(r,deploymentVisual(r.node,r),false,'循環 '+data.group.code)}else{const title=n.kind==='cycle'?n.group.code+' · '+n.members.length+' 項產品':n.department;const subtitle=n.kind==='cycle'?(n.group.active?'循環阻擋中':'目前無等待循環'):'受影響下游 '+n.members.length+' 項';svg=this.summarySVG(title,subtitle,n.kind==='cycle'?n.group.members.map(id=>this.name(id)).slice(0,3):n.members.slice(0,3).map(id=>this.name(id)),n.kind==='cycle'&&n.group.active)}elements.push({group:'nodes',data:{id:n.id,members:n.members,kind:n.kind,cycleKey:n.group?.key,department:n.kind==='downstream'?n.id.slice(11):'',svg},position:{x:n.x,y:n.y}})}for(const e of data.edges){const plan=e.edge&&this.overrides.get(e.edge.edge_id),met=e.edge&&this.analysis.after.met(e.edge);elements.push({group:'edges',data:{id:e.id,source:e.source,target:e.target,kind:e.kind,edge:e.edge,department:e.department,color:e.kind==='impact'?'#9babb1':plan?'#6c8d82':met?'#a8b9b2':'#95545a',style:e.kind==='impact'||met||plan?'dashed':'solid',label:e.kind==='impact'?'下游影響（彙總）':plan?(plan.mode==='remove'?'試算移除':'試算條件滿足'):''}})}
 const nodeIds=new Set(elements.filter(e=>e.group==='nodes').map(e=>e.data.id));if(elements.some(e=>e.group==='edges'&&(!nodeIds.has(e.data.source)||!nodeIds.has(e.data.target))))throw Error('循環圖依賴端點缺漏');
 if(!data.nodes.length){host.innerHTML='<div class="empty">目前範圍沒有阻擋循環。請切換循環範圍，或檢查其他未滿足條件。</div>';this.o.setCy(null);$('#graphcaption').textContent='循環總覽 · 無符合群組';return;}
 const cy=this.currentCy=cytoscape({container:host,elements,layout:{name:'preset'},pixelRatio:Math.min(2,window.devicePixelRatio||1),textureOnViewport:false,userZoomingEnabled:false,minZoom:.12,maxZoom:2.5,style:[{selector:'node',style:{width:285,height:154,shape:'roundrectangle','background-image':'data(svg)','background-fit':'contain','background-color':'#f7f9f8','border-color':'#a7b8b6','border-width':1.5}},{selector:'edge',style:{width:2,'line-color':'data(color)','target-arrow-color':'data(color)','target-arrow-shape':'triangle','line-style':'data(style)','curve-style':'bezier',label:'data(label)','font-size':10,'text-background-color':'#fff','text-background-opacity':.9,'text-background-padding':3,'text-rotation':'autorotate'}},{selector:'.cycle-focus',style:{'border-color':'#7a3e43','border-width':5}},{selector:'.cycle-edge-focus',style:{width:4,'line-color':'#6e303b','target-arrow-color':'#6e303b'}}]});
 this.o.bindViewport(cy);cy.on('tap','node',evt=>{const n=evt.target;if(n.data('kind')==='cycle')this.select(n.data('cycleKey'));else if(n.data('kind')==='product'){this.focusProduct(n.data('members')[0]);this.refreshProductButton()}else this.showDownstream(n.data('department'))});cy.on('tap','edge',evt=>{if(evt.target.data('kind')==='gate'){this.edge=evt.target.data('edge').edge_id;cy.edges().removeClass('cycle-edge-focus');evt.target.addClass('cycle-edge-focus');this.o.openEdge()}else this.showDownstream(evt.target.data('department'))});cy.on('mouseover','node',evt=>{if(evt.target.data('kind')==='product'){this.o.hover(evt);if(this.overrides.size){const id=evt.target.data('members')[0],before=this.analysis.before.results.get(id),after=this.analysis.after.results.get(id),tip=$('#graphHover');if(tip)tip.insertAdjacentHTML('beforeend',`<div class="simulation-status">循環依賴調整（僅此工作區）<br>必要條件：${before.complete}／${before.total} → ${after.complete}／${after.total}</div>`)}}});cy.on('mouseout','node',this.o.hideHover);host.addEventListener('pointerleave',this.o.hideHover);this.o.setCy(cy);graphViewports.mount(cy,this.o.viewportKey()+'|'+(this.selected||'overview'),cy.nodes().filter(n=>n.data('kind')==='product'));this.o.zoomUI();if(this.product)this.focusProduct(this.product);host.dataset.cycleGroup=this.selected||'';host.dataset.cycleMembers=String(data.group?.members.length||0);host.dataset.cycleEdges=String(data.edges.filter(e=>e.kind==='gate').length);$('#graphcaption').textContent=data.group?data.group.code+' · 完整環內 '+data.group.members.length+' 項產品／'+data.group.internal.length+' 條條件 · '+(data.group.active?'循環阻擋中':'目前無阻擋循環'):'循環群組總覽 · 點選群組查看內部，不直接展開全部下游';}
 summarySVG(title,sub,names,blocking){const lines=[title,sub,...names];return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1710" height="924" viewBox="0 0 285 154"><rect width="285" height="154" rx="9" fill="${blocking?'#f7eeee':'#f0f5f3'}"/><path d="M3 8V146" stroke="${blocking?'#95545a':'#7b9c8c'}" stroke-width="5"/>${lines.map((text,i)=>`<text x="16" y="${27+i*25}" font-family="Arial,sans-serif" font-size="${i?11:14}" fill="#314b57" font-weight="${i?400:600}">${escape(text.length>34?text.slice(0,33)+'…':text)}</text>`).join('')}</svg>`)}
 refreshProductButton(){const tools=$('#cycleWorkbench .cycle-selected > .tools');if(!tools)return;let button=tools.querySelector('[data-cycle-product-evidence]');if(!button){button=document.createElement('button');tools.append(button)}button.dataset.cycleProductEvidence=this.product;button.textContent='產品正式證據';}
 showDownstream(dept){const group=this.analysis.groups.find(g=>g.key===this.selected);if(!group)return;const by=new Map();for(const id of group.downstream){const n=this.analysis.before.by.get(id);if(dept&&n.department_id!==dept)continue;if(!by.has(n.department_name))by.set(n.department_name,[]);by.get(n.department_name).push(id)}const host=$('#cycleDownstreamList');host.innerHTML=`<details open class="cycle-downstream"><summary>受影響下游清單 · ${[...by.values()].flat().length} 項產品</summary>${[...by].map(([name,ids])=>`<details><summary>${escape(name)} · ${ids.length} 項</summary>${ids.map(id=>{const r=this.analysis.after.results.get(id);return `<div>${escape(this.name(id))}<small>${r.candidate?'前置就緒':r.execution==='done'?'已完成':r.execution==='active'?'部署中':'尚有其他條件'} · ${r.complete}／${r.total}</small></div>`}).join('')}</details>`).join('')}</details>`;host.scrollIntoView({behavior:'smooth',block:'nearest'});}
 edgePane(){this.ensure();const e=this.analysis.before.gates.find(e=>e.edge_id===this.edge);if(!e)return '<p>請點選環內依賴查看。</p>';const source=this.analysis.before.by.get(e.source),plan=this.overrides.get(e.edge_id),selected=this.analysis.groups.find(g=>g.key===this.selected),candidates=selected?cycleCandidates(this.analysis.after,selected):[];return `<div class="cycle-edge-detail"><h2>循環依賴檢討</h2><div class="path">${escape(this.name(e.source))} → ${escape(this.name(e.target))}</div><dl><dt>原始要求</dt><dd>${escape(e.temporal_constraint.predecessor_state||'Ready')} · 版本 ${escape(e.temporal_constraint.required_version||'未限制')}</dd><dt>目前證據</dt><dd>${escape(source.status)} · ${escape(source.version)}<br>${escape((source.milestones||[]).join('、')||'未提供里程碑')}<br>${escape(source.observed_at||'時間缺漏')}</dd><dt>責任與依據</dt><dd>${escape(source.department_name)} · ${escape(source.owner_team)}<br>${escape(e.rationale||'必要部署條件')}</dd></dl><p>${candidates.includes(e.edge_id)?'此依賴屬於結構檢討候選組合。':'可比較此依賴的調整方案。'}候選不代表可直接取消，也不保證只調整一條就解除全部循環。</p><label>方案類型<select id="cyclePlanKind"><option value="exception" ${(!plan||plan.kind==='exception')?'selected':''}>例外允許（假設此條件已核准豁免）</option><option value="remove" ${plan?.kind==='remove'?'selected':''}>修正誤建依賴（試算移除）</option><option value="milestone" ${plan?.kind==='milestone'?'selected':''}>改用較早里程碑（假設證據已通過）</option><option value="bootstrap" ${plan?.kind==='bootstrap'?'selected':''}>Bootstrap／替代服務（假設已驗證）</option></select></label><label>責任人／團隊<input id="cyclePlanOwner" value="${escape(plan?.owner||source.owner_team||'')}" required></label><label>調整理由<textarea id="cyclePlanReason" required rows="3">${escape(plan?.reason||'')}</textarea></label><label id="cycleConditionLabel" ${['milestone','bootstrap'].includes(plan?.kind)?'':'hidden'}>替代條件／較早里程碑<input id="cyclePlanCondition" value="${escape(plan?.condition||'')}"></label><p class="notice">只有本循環工作區會套用方案；不會把來源產品標記為完成。里程碑／替代服務方案是在「替代條件已通過驗證」前提下試算，不代表現有證據已足夠。</p><div id="cyclePlanError" role="alert"></div><button data-cycle-apply class="primary">${plan?'更新':'套用'}解除試算</button>${plan?`<button data-cycle-remove="${escape(e.edge_id)}">取消此調整</button>`:''}</div>`;}
 apply(){const e=this.analysis.before.gates.find(e=>e.edge_id===this.edge),kind=$('#cyclePlanKind').value,owner=$('#cyclePlanOwner').value.trim(),reason=$('#cyclePlanReason').value.trim(),condition=$('#cyclePlanCondition').value.trim();if(!owner||!reason||(['milestone','bootstrap'].includes(kind)&&!condition)){$('#cyclePlanError').textContent='請填寫責任人／團隊、調整理由及適用的替代條件。';return}const labels={exception:'例外豁免',remove:'修正誤建依賴',milestone:'較早里程碑已驗證（假設）',bootstrap:'替代服務已驗證（假設）'};this.overrides.set(e.edge_id,{mode:kind==='remove'?'remove':'satisfy',kind,kindLabel:labels[kind],owner,reason,condition,sourceName:this.name(e.source),targetName:this.name(e.target)});this.refresh();}
 click(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.cycleSelect)this.select(b.dataset.cycleSelect);if(b.hasAttribute('data-cycle-back')){this.selected=null;this.product=null;this.edge=null;this.refresh()}if(b.hasAttribute('data-cycle-downstream')){this.downstream=!this.downstream;this.refresh();if(this.downstream)this.showDownstream()}if(b.dataset.cycleEdge){this.edge=b.dataset.cycleEdge;this.o.openEdge()}if(b.dataset.cycleProductEvidence)this.o.evidence(b.dataset.cycleProductEvidence);if(b.hasAttribute('data-cycle-apply'))this.apply();if(b.dataset.cycleRemove){this.overrides.delete(b.dataset.cycleRemove);this.refresh()}if(b.hasAttribute('data-cycle-reset')){this.overrides.clear();this.refresh()}if(b.hasAttribute('data-cycle-export')){const a=this.analysis,payload={factory:a.before.ctx.factory.factory_id,profile:a.before.ctx.profile,snapshot:a.before.ctx.factory.snapshot_at,kind:'cycle-decision-draft',formalDataChanged:false,productCompletionAssumptions:[...this.o.productTrials()],dependencyAdjustments:[...this.overrides].map(([edge_id,p])=>({edge_id,...p})),result:{blockingGroups:a.activeGroups,newlyReady:a.newlyReady.map(r=>({product:r.node.product_name,department:r.node.department_name})),remainingUnmetGates:a.after.gates.filter(e=>!a.after.met(e)).length}};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='cycle-decision-draft.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
 change(e){if(e.target.id==='cycleScope'){this.scope=e.target.value;this.selected=null;this.product=null;this.refresh()}if(e.target.id==='cyclePlanKind'){const needed=['milestone','bootstrap'].includes(e.target.value);$('#cycleConditionLabel').hidden=!needed;$('#cyclePlanCondition').required=needed;}}
}
